import { Guid } from '@cratis/fundamentals';
import { useState } from 'react';
import { LiveAuthors } from './arc/Authors/Listing';
import { RegisterAuthor, RenameAuthor } from './arc/Authors/Registration';

// Everything under ./arc is generated by `mix compile` in Samples/phoenix. It is opt-in: the
// backend generates TypeScript only because mix.exs adds the :arc compiler.

export const App = () => {
    // A live query: the server pushes a new list whenever Chronicle changes an author.
    const [authors] = LiveAuthors.use();

    // A command with client-side validation generated from the same rules the server enforces.
    const [register, setRegisterValues] = RegisterAuthor.use({ id: Guid.create(), name: '' });
    const [message, setMessage] = useState('');

    const submit = async () => {
        const result = await register.execute();
        if (result.isSuccess) {
            setMessage('Registered.');
            setRegisterValues({ id: Guid.create(), name: '' });
        } else if (!result.isAuthorized) {
            setMessage(`Not allowed: ${result.authorizationFailureReason}`);
        } else {
            setMessage(result.validationResults.map(validation => validation.message).join(' '));
        }
    };

    const rename = async (id: Guid) => {
        const command = new RenameAuthor();
        command.id = id;
        command.name = `Renamed ${Date.now()}`;
        const result = await command.execute();
        setMessage(result.isSuccess ? 'Renamed.' : `Not allowed: ${result.authorizationFailureReason}`);
    };

    return (
        <main>
            <h1>Authors</h1>
            {message && <p role="status">{message}</p>}

            <ul>
                {authors.data.map(author => (
                    <li key={author.id.toString()}>
                        {author.name}{' '}
                        <button onClick={() => rename(author.id)}>Rename (editors only)</button>
                    </li>
                ))}
            </ul>

            <form onSubmit={event => { event.preventDefault(); void submit(); }}>
                <label>
                    Name{' '}
                    <input
                        value={register.name ?? ''}
                        onChange={event => setRegisterValues({ name: event.target.value })}
                    />
                </label>
                <button type="submit">Register</button>
            </form>
        </main>
    );
};
